const libraryV2 = "\"use client\";\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport { api } from \"@/lib/api\";\nimport type { Project } from \"@/lib/types\";\n\nfunction statusLabel(status?: string | null) {\n  const s=String(status||\"\").toLowerCase();\n  if([\"complete\",\"ready\",\"publish\"].some(x=>s.includes(x))) return \"Sẵn sàng\";\n  if([\"draft\",\"plan\",\"generat\"].some(x=>s.includes(x))) return \"Đang soạn\";\n  return status||\"Đang xử lý\";\n}\n\nconst tones=[\n  \"from-sky-500 via-cyan-400 to-emerald-300\",\n  \"from-indigo-800 via-violet-700 to-fuchsia-500\",\n  \"from-emerald-500 via-lime-400 to-cyan-300\",\n  \"from-amber-500 via-orange-400 to-rose-400\",\n  \"from-slate-800 via-blue-800 to-indigo-600\",\n];\n\nexport default function LibraryPage(){\n  const [projects,setProjects]=useState<Project[]>([]);\n  const [loading,setLoading]=useState(true);\n  const [error,setError]=useState(\"\");\n  const [q,setQ]=useState(\"\");\n  const [subject,setSubject]=useState(\"all\");\n  const [status,setStatus]=useState(\"all\");\n  const [view,setView]=useState<\"grid\"|\"list\">(\"grid\");\n\n  useEffect(()=>{api.listProjects().then(setProjects).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[]);\n\n  const subjects=useMemo(()=>Array.from(new Set(projects.map(p=>p.subject).filter(Boolean) as string[])).sort(),[projects]);\n  const rows=useMemo(()=>projects.filter(p=>{\n    const text=[p.title,p.subject,p.grade].filter(Boolean).join(\" \").toLowerCase();\n    const okQ=!q.trim()||text.includes(q.trim().toLowerCase());\n    const okSub=subject===\"all\"||p.subject===subject;\n    const s=statusLabel(p.status);\n    const okStatus=status===\"all\"||s===status;\n    return okQ&&okSub&&okStatus;\n  }),[projects,q,subject,status]);\n\n  return <main className=\"min-h-screen bg-[#f6f8fe] text-slate-900\">\n    <header className=\"sticky top-0 z-40 border-b border-indigo-100 bg-white/95 backdrop-blur\">\n      <div className=\"flex h-[68px] items-center gap-4 px-4 md:px-7\">\n        <button onClick={()=>location.href=\"/\"} className=\"flex items-center gap-2.5\"><span className=\"grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-indigo-600 to-violet-500 text-white\">▰</span><span className=\"hidden text-lg font-black text-indigo-800 sm:block\">AI E-Learning Studio</span></button>\n        <div className=\"hidden h-7 w-px bg-slate-200 lg:block\"/>\n        <div className=\"hidden text-sm font-semibold text-slate-500 lg:block\">Thư viện bài giảng</div>\n        <div className=\"ml-auto flex items-center gap-2\"><button onClick={()=>location.href=\"/projects/new\"} className=\"rounded-xl bg-indigo-600 px-4 py-2.5 text-xs font-black text-white\">＋ Tạo bài mới</button></div>\n      </div>\n    </header>\n\n    <div className=\"flex\">\n      <aside className=\"sticky top-[68px] hidden h-[calc(100vh-68px)] w-[214px] shrink-0 border-r border-indigo-100 bg-white p-3 lg:block\">\n        <div className=\"px-3 pb-3 pt-2 text-[10px] font-black uppercase tracking-[.18em] text-slate-400\">Không gian làm việc</div>\n        {[\n          [\"⌂\",\"Trang chủ\",\"/\"],\n          [\"✦\",\"Tạo bài giảng\",\"/projects/new\"],\n          [\"▣\",\"Thư viện\",\"/library\"],\n          [\"♙\",\"Lớp học\",\"/classrooms\"],\n          [\"♟\",\"Học sinh\",\"/learn\"],\n        ].map(([i,l,h])=><button key={l} onClick={()=>location.href=h} className={\"mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold \"+(l===\"Thư viện\"?\"bg-indigo-50 text-indigo-700\":\"text-slate-600 hover:bg-slate-50\")}><span className=\"w-5 text-center\">{i}</span>{l}</button>)}\n      </aside>\n\n      <section className=\"min-w-0 flex-1 p-4 md:p-7\">\n        <div className=\"mx-auto max-w-[1420px]\">\n          <div className=\"flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between\">\n            <div><div className=\"text-[11px] font-black uppercase tracking-[.18em] text-indigo-600\">Kho nội dung</div><h1 className=\"mt-1 text-3xl font-black tracking-tight\">Thư viện bài giảng</h1><p className=\"mt-1 text-sm text-slate-500\">Tìm, mở và tiếp tục chỉnh sửa tất cả bài giảng trong workspace.</p></div>\n            <div className=\"flex items-center gap-2\"><button onClick={()=>setView(\"grid\")} className={\"rounded-xl border px-3 py-2 text-xs font-black \"+(view===\"grid\"?\"border-indigo-200 bg-indigo-50 text-indigo-700\":\"border-slate-200 bg-white text-slate-500\")}>▦ Lưới</button><button onClick={()=>setView(\"list\")} className={\"rounded-xl border px-3 py-2 text-xs font-black \"+(view===\"list\"?\"border-indigo-200 bg-indigo-50 text-indigo-700\":\"border-slate-200 bg-white text-slate-500\")}>☰ Danh sách</button></div>\n          </div>\n\n          <div className=\"mt-6 grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm md:grid-cols-[1fr_220px_180px]\">\n            <div className=\"relative\"><span className=\"absolute left-3 top-1/2 -translate-y-1/2 text-slate-400\">⌕</span><input value={q} onChange={e=>setQ(e.target.value)} className=\"input pl-9\" placeholder=\"Tìm theo tên bài, môn học, lớp…\"/></div>\n            <select value={subject} onChange={e=>setSubject(e.target.value)} className=\"input\"><option value=\"all\">Tất cả môn học</option>{subjects.map(s=><option key={s} value={s}>{s}</option>)}</select>\n            <select value={status} onChange={e=>setStatus(e.target.value)} className=\"input\"><option value=\"all\">Tất cả trạng thái</option><option>Đang soạn</option><option>Sẵn sàng</option><option>Đang xử lý</option></select>\n          </div>\n\n          <div className=\"mt-5 flex items-center justify-between\"><div className=\"text-sm font-black\">{rows.length} bài giảng</div><div className=\"text-xs text-slate-400\">{projects.length} bài trong workspace</div></div>\n\n          {loading&&<div className=\"mt-4 rounded-2xl border bg-white p-12 text-center text-sm text-slate-400\">Đang tải thư viện…</div>}\n          {error&&<div className=\"mt-4 rounded-2xl border border-rose-200 bg-rose-50 p-5 text-sm text-rose-700\">{error}</div>}\n          {!loading&&!error&&rows.length===0&&<div className=\"mt-4 rounded-3xl border-2 border-dashed border-indigo-200 bg-white p-12 text-center\"><div className=\"text-4xl\">▣</div><div className=\"mt-3 font-black\">Không tìm thấy bài giảng phù hợp</div><div className=\"mt-1 text-sm text-slate-400\">Thử đổi bộ lọc hoặc tạo bài mới.</div><button onClick={()=>location.href=\"/projects/new\"} className=\"mt-5 rounded-xl bg-indigo-600 px-4 py-2.5 text-xs font-black text-white\">Tạo bài giảng</button></div>}\n\n          {view===\"grid\"?<div className=\"mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4\">{rows.map((p,i)=><article key={p.id} className=\"overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm transition hover:-translate-y-1 hover:shadow-xl\">\n            <button onClick={()=>location.href=\"/projects/\"+p.id+\"/editor\"} className={\"relative block h-36 w-full bg-gradient-to-br \"+tones[i%tones.length]+\" p-4 text-left text-white\"}><div className=\"absolute inset-0 bg-black/5\"/><div className=\"relative flex h-full flex-col justify-between\"><span className=\"w-fit rounded-lg bg-black/20 px-2 py-1 text-[9px] font-black uppercase backdrop-blur\">{p.subject||\"Bài học\"}</span><span className=\"text-4xl\">{[\"🌍\",\"💻\",\"🌱\",\"📐\",\"🔬\"][i%5]}</span></div></button>\n            <div className=\"p-4\"><button onClick={()=>location.href=\"/projects/\"+p.id+\"/editor\"} className=\"line-clamp-2 min-h-10 text-left text-sm font-black leading-5 hover:text-indigo-700\">{p.title}</button><div className=\"mt-2 text-[10px] text-slate-400\">{[p.subject,p.grade?\"Lớp \"+p.grade:null,p.duration_minutes?p.duration_minutes+\" phút\":null].filter(Boolean).join(\" · \")||\"Chưa có metadata\"}</div><div className=\"mt-4 flex items-center justify-between\"><span className=\"rounded-full bg-indigo-50 px-2 py-1 text-[9px] font-black text-indigo-700\">{statusLabel(p.status)}</span><div className=\"flex gap-1\"><button onClick={()=>location.href=\"/projects/\"+p.id+\"/analytics\"} className=\"rounded-lg border border-slate-200 px-2 py-1 text-[9px] font-black text-slate-500\">Analytics</button><button onClick={()=>location.href=\"/projects/\"+p.id+\"/editor\"} className=\"rounded-lg bg-slate-900 px-2 py-1 text-[9px] font-black text-white\">Mở</button></div></div></div>\n          </article>)}</div>:\n          <div className=\"mt-4 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm\"><div className=\"overflow-x-auto\"><table className=\"w-full min-w-[820px] text-left\"><thead className=\"bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400\"><tr><th className=\"px-4 py-3\">Bài giảng</th><th>Môn / lớp</th><th>Thời lượng</th><th>Trạng thái</th><th className=\"text-right\">Thao tác</th></tr></thead><tbody>{rows.map(p=><tr key={p.id} className=\"border-t border-slate-100\"><td className=\"px-4 py-3\"><div className=\"font-black\">{p.title}</div></td><td className=\"text-xs text-slate-500\">{[p.subject,p.grade?\"Lớp \"+p.grade:null].filter(Boolean).join(\" · \")||\"—\"}</td><td className=\"text-xs text-slate-500\">{p.duration_minutes?p.duration_minutes+\" phút\":\"—\"}</td><td><span className=\"rounded-full bg-indigo-50 px-2 py-1 text-[9px] font-black text-indigo-700\">{statusLabel(p.status)}</span></td><td className=\"px-4 text-right\"><button onClick={()=>location.href=\"/projects/\"+p.id+\"/analytics\"} className=\"mr-2 rounded-lg border px-2.5 py-1.5 text-[10px] font-black\">Analytics</button><button onClick={()=>location.href=\"/projects/\"+p.id+\"/editor\"} className=\"rounded-lg bg-indigo-600 px-3 py-1.5 text-[10px] font-black text-white\">Mở Editor</button></td></tr>)}</tbody></table></div></div>}\n        </div>\n      </section>\n    </div>\n  </main>;\n}\n";
fs.writeFileSync(path.join(root, "frontend/app/library/page.tsx"), libraryV2);

