const exportCenterV2 = "\"use client\";\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport { api } from \"@/lib/api\";\nimport type { ExportFormat, Project } from \"@/lib/types\";\n\ntype ExportRow = {\n  id?: string;\n  format?: string;\n  file_name?: string | null;\n  download_url?: string | null;\n  status?: string | null;\n  created_at?: string | null;\n  size_bytes?: number | null;\n};\n\nconst formats:Array<{format:ExportFormat;icon:string;name:string;desc:string;badge:string}> = [\n  {format:\"pptx\",icon:\"P\",name:\"PowerPoint\",desc:\"Bản trình chiếu có thể tiếp tục chỉnh sửa.\",badge:\"PPTX\"},\n  {format:\"pdf\",icon:\"PDF\",name:\"PDF\",desc:\"Bản đọc nhanh, bố cục cố định để chia sẻ hoặc in.\",badge:\"PDF\"},\n  {format:\"html5\",icon:\"</>\",name:\"HTML5\",desc:\"Bài học web tương tác có thể chạy trên trình duyệt.\",badge:\"WEB\"},\n  {format:\"scorm12\",icon:\"S1\",name:\"SCORM 1.2\",desc:\"Gói ZIP tương thích rộng với các hệ thống LMS.\",badge:\"LMS\"},\n  {format:\"scorm2004\",icon:\"S4\",name:\"SCORM 2004\",desc:\"Gói LMS có tracking và resume nâng cao.\",badge:\"LMS+\"},\n];\n\nexport default function ExportCenter({params}:{params:Promise<{projectId:string}>}) {\n  const [projectId,setProjectId]=useState(\"\");\n  const [project,setProject]=useState<Project|null>(null);\n  const [rows,setRows]=useState<ExportRow[]>([]);\n  const [busy,setBusy]=useState(\"\");\n  const [error,setError]=useState(\"\");\n  const [notice,setNotice]=useState(\"\");\n  const [includeNotes,setIncludeNotes]=useState(true);\n  const [includeSources,setIncludeSources]=useState(true);\n  const [includeQuiz,setIncludeQuiz]=useState(true);\n\n  useEffect(()=>{params.then(x=>setProjectId(x.projectId))},[params]);\n  async function load(id=projectId){\n    if(!id)return;\n    try{\n      const [p,e]=await Promise.all([api.getProject(id),api.listExports(id)]);\n      setProject(p); setRows(e as unknown as ExportRow[]);\n    }catch(e){setError(e instanceof Error?e.message:\"Không tải được dữ liệu xuất bài\");}\n  }\n  useEffect(()=>{if(projectId)load(projectId)},[projectId]);\n\n  async function exportNow(format:ExportFormat){\n    if(!projectId)return;\n    setError(\"\");setNotice(\"\");setBusy(format);\n    try{\n      const run=await api.createExport(projectId,format,{\n        include_notes:includeNotes,\n        include_sources:includeSources,\n        include_quiz:includeQuiz,\n      });\n      setNotice(\"Đã tạo \"+(run.file_name||format.toUpperCase())+\".\");\n      await load(projectId);\n      const url=api.exportDownloadUrl(run);\n      if(url) window.location.href=url;\n    }catch(e){setError(e instanceof Error?e.message:\"Xuất bài thất bại\");}\n    finally{setBusy(\"\");}\n  }\n\n  const meta=useMemo(()=>[project?.subject,project?.grade?\"Lớp \"+project.grade:null,project?.duration_minutes?project.duration_minutes+\" phút\":null].filter(Boolean).join(\" · \"),[project]);\n  if(!project)return <main className=\"grid min-h-screen place-items-center bg-[#f6f8fe] text-sm text-slate-500\">{error||\"Đang mở trung tâm xuất bài…\"}</main>;\n\n  return <main className=\"min-h-screen bg-[#f6f8fe] text-slate-900\">\n    <header className=\"sticky top-0 z-40 border-b border-indigo-100 bg-white/95 backdrop-blur\">\n      <div className=\"flex h-[68px] items-center gap-3 px-4 md:px-6\">\n        <button onClick={()=>location.href=\"/projects/\"+projectId+\"/editor\"} className=\"grid h-9 w-9 place-items-center rounded-xl border border-slate-200 bg-white text-sm font-black\">←</button>\n        <div className=\"hidden items-center gap-2 md:flex\"><span className=\"grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-indigo-600 to-violet-500 text-white\">▰</span><span className=\"font-black text-indigo-800\">AI E-Learning Studio</span></div>\n        <div className=\"hidden h-7 w-px bg-slate-200 md:block\"/>\n        <div className=\"min-w-0 flex-1\"><div className=\"truncate text-sm font-black\">Xuất bài giảng</div><div className=\"truncate text-[10px] text-slate-400\">{project.title}</div></div>\n        <button onClick={()=>location.href=\"/projects/\"+projectId+\"/editor\"} className=\"rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-600\">Về Editor</button>\n      </div>\n    </header>\n\n    <div className=\"mx-auto max-w-6xl p-4 md:p-8\">\n      {(error||notice)&&<div className={\"mb-5 rounded-2xl border p-4 text-sm font-semibold \"+(error?\"border-rose-200 bg-rose-50 text-rose-700\":\"border-emerald-200 bg-emerald-50 text-emerald-700\")}>{error||notice}</div>}\n\n      <section className=\"overflow-hidden rounded-[28px] bg-gradient-to-r from-indigo-700 via-violet-600 to-indigo-500 p-6 text-white shadow-xl shadow-indigo-100 md:p-8\">\n        <div className=\"grid gap-6 md:grid-cols-[1fr_auto] md:items-center\">\n          <div><div className=\"text-[10px] font-black uppercase tracking-[.18em] text-indigo-100\">Export Center</div><h1 className=\"mt-2 text-2xl font-black md:text-3xl\">{project.title}</h1><p className=\"mt-2 text-sm text-indigo-100\">{meta||\"Bài giảng E-Learning\"}</p><p className=\"mt-4 max-w-2xl text-sm leading-6 text-white/80\">Chọn định dạng phù hợp để trình chiếu, in, chia sẻ trên web hoặc đưa vào LMS. Mỗi lần xuất được lưu lại để có thể tải lại.</p></div>\n          <div className=\"grid h-28 w-28 place-items-center rounded-[28px] border border-white/20 bg-white/10 text-5xl backdrop-blur\">⇩</div>\n        </div>\n      </section>\n\n      <div className=\"mt-6 grid gap-5 lg:grid-cols-[1fr_320px]\">\n        <section>\n          <div className=\"mb-3\"><h2 className=\"text-lg font-black\">Chọn định dạng</h2><p className=\"text-xs text-slate-400\">Định dạng được tạo trực tiếp từ phiên bản bài giảng hiện tại.</p></div>\n          <div className=\"space-y-3\">{formats.map(f=><div key={f.format} className=\"flex flex-col gap-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:flex-row sm:items-center\">\n            <div className=\"grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-indigo-50 text-xs font-black text-indigo-700\">{f.icon}</div>\n            <div className=\"min-w-0 flex-1\"><div className=\"flex items-center gap-2\"><h3 className=\"font-black\">{f.name}</h3><span className=\"rounded-md bg-slate-100 px-2 py-0.5 text-[9px] font-black text-slate-500\">{f.badge}</span></div><p className=\"mt-1 text-xs leading-5 text-slate-500\">{f.desc}</p></div>\n            <button disabled={!!busy} onClick={()=>exportNow(f.format)} className=\"rounded-xl bg-indigo-600 px-5 py-2.5 text-xs font-black text-white shadow-md shadow-indigo-100 disabled:opacity-40\">{busy===f.format?\"Đang tạo…\":\"Xuất\"}</button>\n          </div>)}</div>\n        </section>\n\n        <aside className=\"space-y-4\">\n          <section className=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm\"><h2 className=\"text-sm font-black\">Tùy chọn xuất</h2><p className=\"mt-1 text-[11px] leading-5 text-slate-400\">Áp dụng cho lần xuất tiếp theo.</p>\n            <div className=\"mt-4 space-y-3\">{[\n              [\"Kèm lời giảng / ghi chú\",includeNotes,setIncludeNotes],\n              [\"Kèm nguồn tham chiếu\",includeSources,setIncludeSources],\n              [\"Kèm câu hỏi tương tác\",includeQuiz,setIncludeQuiz],\n            ].map(([label,value,setter])=><label key={String(label)} className=\"flex items-center justify-between gap-3 rounded-xl bg-slate-50 px-3 py-3 text-xs font-bold text-slate-600\"><span>{String(label)}</span><input type=\"checkbox\" checked={Boolean(value)} onChange={e=>(setter as (v:boolean)=>void)(e.target.checked)} className=\"h-4 w-4 accent-indigo-600\"/></label>)}\n          </section>\n\n          <section className=\"rounded-2xl border border-indigo-100 bg-indigo-50 p-5\"><div className=\"text-xs font-black text-indigo-800\">Gợi ý</div><p className=\"mt-2 text-[11px] leading-5 text-indigo-700\">PPTX phù hợp khi giáo viên muốn chỉnh thêm. HTML5 dùng cho chia sẻ web. SCORM dành cho LMS cần theo dõi tiến độ và điểm.</p></section>\n        </aside>\n      </div>\n\n      <section className=\"mt-7\">\n        <div className=\"mb-3 flex items-end justify-between\"><div><h2 className=\"text-lg font-black\">Lịch sử xuất bài</h2><p className=\"text-xs text-slate-400\">{rows.length} file đã được tạo</p></div><button onClick={()=>load(projectId)} className=\"rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-500\">Làm mới</button></div>\n        {!rows.length?<div className=\"rounded-2xl border-2 border-dashed border-slate-200 bg-white p-8 text-center text-sm text-slate-400\">Chưa có file xuất nào.</div>:\n        <div className=\"overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm\"><div className=\"overflow-x-auto\"><table className=\"w-full min-w-[700px] text-left\"><thead className=\"bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400\"><tr><th className=\"px-4 py-3\">File</th><th>Định dạng</th><th>Trạng thái</th><th>Thời gian</th><th className=\"text-right\">Tải</th></tr></thead><tbody>{rows.map((r,i)=>{const url=r.download_url?api.exportDownloadUrl(r as never):\"\";return <tr key={r.id||i} className=\"border-t border-slate-100\"><td className=\"px-4 py-3 text-sm font-black\">{r.file_name||\"Export \"+(i+1)}</td><td className=\"text-xs font-bold uppercase text-indigo-600\">{r.format||\"—\"}</td><td className=\"text-xs text-slate-500\">{r.status||\"completed\"}</td><td className=\"text-xs text-slate-400\">{r.created_at?new Date(r.created_at).toLocaleString(\"vi-VN\"):\"—\"}</td><td className=\"px-4 text-right\">{url?<button onClick={()=>location.href=url} className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-[10px] font-black text-white\">Tải lại</button>:<span className=\"text-[10px] text-slate-300\">—</span>}</td></tr>})}</tbody></table></div></div>}\n      </section>\n    </div>\n  </main>;\n}\n";
fs.writeFileSync(path.join(root, "frontend/app/projects/[projectId]/export/page.tsx"), exportCenterV2);

const topBarExportPath = path.join(root, "frontend/components/editor/TopBar.tsx");
let topBarExport = fs.readFileSync(topBarExportPath, "utf8");
topBarExport = topBarExport.replace('<div className="relative"><button disabled={!!busy} onClick={() => setOpen((x) => !x)} className="rounded-xl bg-indigo-600 px-4 py-2 text-xs font-black text-white shadow-lg shadow-indigo-100 disabled:opacity-40">Xuất bài ▾</button>', '<div className="relative"><button disabled={!!busy} onClick={() => { window.location.href = "/projects/"+project.id+"/export"; }} className="rounded-xl bg-indigo-600 px-4 py-2 text-xs font-black text-white shadow-lg shadow-indigo-100 disabled:opacity-40">Xuất bài →</button>');
topBarExport = topBarExport.replace('{open&&<div className="absolute right-0 top-11 z-[90] w-64 overflow-hidden rounded-2xl border border-slate-200 bg-white p-2 shadow-2xl">', '{false&&open&&<div className="absolute right-0 top-11 z-[90] w-64 overflow-hidden rounded-2xl border border-slate-200 bg-white p-2 shadow-2xl">');
fs.writeFileSync(topBarExportPath, topBarExport);

fs.mkdirSync(path.join(root, "frontend/app/students"), {recursive:true});
fs.mkdirSync(path.join(root, "frontend/app/reports"), {recursive:true});
fs.writeFileSync(path.join(root, "frontend/app/students/page.tsx"), "\"use client\";\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport { api } from \"@/lib/api\";\nimport type { Classroom, ClassroomMember } from \"@/lib/types\";\n\ntype StudentRow={key:string;name:string;email:string;classes:Array<{id:string;name:string}>};\n\nexport default function StudentsPage(){\n  const [rooms,setRooms]=useState<Classroom[]>([]);\n  const [members,setMembers]=useState<Record<string,ClassroomMember[]>>({});\n  const [q,setQ]=useState(\"\");\n  const [roomFilter,setRoomFilter]=useState(\"all\");\n  const [loading,setLoading]=useState(true);\n  const [error,setError]=useState(\"\");\n\n  useEffect(()=>{(async()=>{\n    try{\n      const rs=await api.listClassrooms(); setRooms(rs);\n      const pairs=await Promise.all(rs.map(async r=>[r.id,await api.classroomMembers(r.id)] as const));\n      setMembers(Object.fromEntries(pairs));\n    }catch(e){setError(e instanceof Error?e.message:\"Không tải được danh sách học sinh\")}\n    finally{setLoading(false)}\n  })()},[]);\n\n  const rows=useMemo(()=>{\n    const map=new Map<string,StudentRow>();\n    for(const room of rooms){\n      for(const m of members[room.id]||[]){\n        if(m.member_role!==\"student\")continue;\n        const email=m.email||\"\";\n        const key=email||m.id;\n        const cur=map.get(key)||{key,name:m.display_name||email||\"Học sinh\",email,classes:[]};\n        cur.classes.push({id:room.id,name:room.name});\n        map.set(key,cur);\n      }\n    }\n    return Array.from(map.values()).filter(s=>{\n      const okQ=!q.trim()||(s.name+\" \"+s.email).toLowerCase().includes(q.trim().toLowerCase());\n      const okRoom=roomFilter===\"all\"||s.classes.some(x=>x.id===roomFilter);\n      return okQ&&okRoom;\n    }).sort((a,b)=>a.name.localeCompare(b.name,\"vi\"));\n  },[rooms,members,q,roomFilter]);\n\n  return <main className=\"min-h-screen bg-[#f6f8fe] text-slate-900\">\n    <header className=\"sticky top-0 z-40 border-b border-indigo-100 bg-white/95 backdrop-blur\"><div className=\"flex h-[68px] items-center gap-4 px-4 md:px-7\"><button onClick={()=>location.href=\"/\"} className=\"flex items-center gap-2.5\"><span className=\"grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-indigo-600 to-violet-500 text-white\">▰</span><span className=\"hidden text-lg font-black text-indigo-800 sm:block\">AI E-Learning Studio</span></button><div className=\"hidden h-7 w-px bg-slate-200 lg:block\"/><span className=\"hidden text-sm font-semibold text-slate-500 lg:block\">Quản lý học sinh</span><div className=\"ml-auto\"><button onClick={()=>location.href=\"/classrooms\"} className=\"rounded-xl bg-indigo-600 px-4 py-2.5 text-xs font-black text-white\">Quản lý lớp học</button></div></div></header>\n    <div className=\"mx-auto max-w-7xl p-4 md:p-8\">\n      <div className=\"flex flex-col gap-3 md:flex-row md:items-end md:justify-between\"><div><div className=\"text-[11px] font-black uppercase tracking-[.18em] text-indigo-600\">Student Management</div><h1 className=\"mt-1 text-3xl font-black\">Học sinh</h1><p className=\"mt-1 text-sm text-slate-500\">Tổng hợp học sinh từ tất cả lớp học bạn đang quản lý.</p></div><div className=\"rounded-2xl border border-indigo-100 bg-white px-5 py-3 shadow-sm\"><div className=\"text-2xl font-black text-indigo-700\">{rows.length}</div><div className=\"text-[10px] font-bold text-slate-400\">học sinh hiển thị</div></div></div>\n\n      <section className=\"mt-6 grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm md:grid-cols-[1fr_260px]\"><input value={q} onChange={e=>setQ(e.target.value)} className=\"input\" placeholder=\"Tìm theo tên hoặc email…\"/><select value={roomFilter} onChange={e=>setRoomFilter(e.target.value)} className=\"input\"><option value=\"all\">Tất cả lớp học</option>{rooms.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></section>\n\n      {loading&&<div className=\"mt-5 rounded-2xl border bg-white p-12 text-center text-sm text-slate-400\">Đang tải học sinh…</div>}\n      {error&&<div className=\"mt-5 rounded-2xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700\">{error}</div>}\n      {!loading&&!error&&<div className=\"mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm\"><div className=\"overflow-x-auto\"><table className=\"w-full min-w-[720px] text-left\"><thead className=\"bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400\"><tr><th className=\"px-4 py-3\">Học sinh</th><th>Email</th><th>Lớp tham gia</th><th className=\"text-right\">Thao tác</th></tr></thead><tbody>{rows.map((s,i)=><tr key={s.key} className=\"border-t border-slate-100\"><td className=\"px-4 py-3\"><div className=\"flex items-center gap-3\"><span className=\"grid h-10 w-10 place-items-center rounded-full bg-indigo-50 text-sm font-black text-indigo-700\">{s.name.slice(0,1).toUpperCase()}</span><div><div className=\"text-sm font-black\">{s.name}</div><div className=\"text-[10px] text-slate-400\">Học sinh #{String(i+1).padStart(3,\"0\")}</div></div></div></td><td className=\"text-xs text-slate-500\">{s.email||\"—\"}</td><td><div className=\"flex flex-wrap gap-1\">{s.classes.map(cl=><button key={cl.id} onClick={()=>location.href=\"/classrooms/\"+cl.id} className=\"rounded-lg bg-indigo-50 px-2 py-1 text-[10px] font-black text-indigo-700\">{cl.name}</button>)}</div></td><td className=\"px-4 text-right\"><button onClick={()=>location.href=\"/classrooms/\"+s.classes[0]?.id} className=\"rounded-lg border border-slate-200 px-3 py-1.5 text-[10px] font-black text-slate-600\">Xem lớp</button></td></tr>)}</tbody></table></div>{!rows.length&&<div className=\"p-10 text-center text-sm text-slate-400\">Chưa có học sinh phù hợp.</div>}</div>}\n    </div>\n  </main>;\n}\n");
fs.writeFileSync(path.join(root, "frontend/app/reports/page.tsx"), "\"use client\";\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport { api } from \"@/lib/api\";\nimport type { AnalyticsSummary, Project } from \"@/lib/types\";\n\ntype Row={project:Project;summary:AnalyticsSummary|null};\n\nfunction pct(v?:number|null){return v==null?\"—\":Math.round(v)+\"%\";}\nfunction val(v?:number|null){return v==null?\"—\":Math.round(v);}\nfunction tone(v?:number|null){if(v==null)return \"bg-slate-200\";if(v>=80)return \"bg-emerald-500\";if(v>=60)return \"bg-indigo-500\";return \"bg-amber-500\";}\n\nexport default function ReportsPage(){\n  const [rows,setRows]=useState<Row[]>([]);\n  const [loading,setLoading]=useState(true);\n  const [error,setError]=useState(\"\");\n  useEffect(()=>{(async()=>{try{\n    const ps=await api.listProjects();\n    const data=await Promise.all(ps.slice(0,24).map(async p=>{try{return {project:p,summary:await api.analyticsSummary(p.id)}}catch{return {project:p,summary:null}}}));\n    setRows(data);\n  }catch(e){setError(e instanceof Error?e.message:\"Không tải được báo cáo\")}finally{setLoading(false)}})()},[]);\n\n  const totals=useMemo(()=>rows.reduce((a,r)=>{const s=r.summary;if(!s)return a;a.learners+=s.learner_count||0;a.attempts+=s.attempt_count||0;a.completedWeighted+=(s.completion_rate||0);a.passWeighted+=(s.pass_rate||0);a.scored+=(s.average_score||0);a.n++;return a},{learners:0,attempts:0,completedWeighted:0,passWeighted:0,scored:0,n:0}),[rows]);\n  const avgCompletion=totals.n?totals.completedWeighted/totals.n:0;\n  const avgPass=totals.n?totals.passWeighted/totals.n:0;\n  const avgScore=totals.n?totals.scored/totals.n:0;\n\n  return <main className=\"min-h-screen bg-[#f6f8fe] text-slate-900\">\n    <header className=\"sticky top-0 z-40 border-b border-indigo-100 bg-white/95 backdrop-blur\"><div className=\"flex h-[68px] items-center gap-4 px-4 md:px-7\"><button onClick={()=>location.href=\"/\"} className=\"flex items-center gap-2.5\"><span className=\"grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-indigo-600 to-violet-500 text-white\">▰</span><span className=\"hidden text-lg font-black text-indigo-800 sm:block\">AI E-Learning Studio</span></button><div className=\"hidden h-7 w-px bg-slate-200 lg:block\"/><span className=\"hidden text-sm font-semibold text-slate-500 lg:block\">Báo cáo & Analytics</span><div className=\"ml-auto\"><button onClick={()=>location.href=\"/library\"} className=\"rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-xs font-black text-slate-600\">Thư viện</button></div></div></header>\n\n    <div className=\"mx-auto max-w-7xl p-4 md:p-8\">\n      <div><div className=\"text-[11px] font-black uppercase tracking-[.18em] text-indigo-600\">Analytics Overview</div><h1 className=\"mt-1 text-3xl font-black\">Báo cáo tổng quan</h1><p className=\"mt-1 text-sm text-slate-500\">Tổng hợp dữ liệu học tập từ các bài giảng trong workspace.</p></div>\n      {error&&<div className=\"mt-5 rounded-2xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700\">{error}</div>}\n      <section className=\"mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-5\">{[\n        [\"Bài giảng\",rows.length,\"▣\"],\n        [\"Người học\",totals.learners,\"♟\"],\n        [\"Lượt học\",totals.attempts,\"↻\"],\n        [\"Hoàn thành\",pct(avgCompletion),\"✓\"],\n        [\"Điểm TB\",val(avgScore),\"★\"],\n      ].map(([l,v,i])=><div key={String(l)} className=\"rounded-2xl border border-slate-200 bg-white p-4 shadow-sm\"><div className=\"flex items-center justify-between\"><span className=\"text-[10px] font-black uppercase tracking-wider text-slate-400\">{l}</span><span className=\"text-indigo-500\">{i}</span></div><div className=\"mt-2 text-2xl font-black\">{v}</div></div>)}</section>\n\n      {loading?<div className=\"mt-5 rounded-2xl border bg-white p-12 text-center text-sm text-slate-400\">Đang tổng hợp analytics…</div>:\n      <div className=\"mt-6 grid gap-5 lg:grid-cols-[1.15fr_.85fr]\">\n        <section className=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm\"><div className=\"flex items-center justify-between\"><div><h2 className=\"font-black\">Hiệu quả theo bài giảng</h2><p className=\"mt-1 text-xs text-slate-400\">Completion và pass rate của từng project.</p></div><span className=\"rounded-lg bg-indigo-50 px-2 py-1 text-[10px] font-black text-indigo-700\">{rows.length} bài</span></div>\n          <div className=\"mt-5 space-y-4\">{rows.map(({project,summary})=><button key={project.id} onClick={()=>location.href=\"/projects/\"+project.id+\"/analytics\"} className=\"block w-full rounded-xl border border-slate-100 p-3 text-left hover:border-indigo-200 hover:bg-indigo-50/30\"><div className=\"flex items-start justify-between gap-4\"><div className=\"min-w-0\"><div className=\"truncate text-sm font-black\">{project.title}</div><div className=\"mt-1 text-[10px] text-slate-400\">{[project.subject,project.grade?\"Lớp \"+project.grade:null].filter(Boolean).join(\" · \")||\"Bài giảng\"}</div></div><div className=\"shrink-0 text-xs font-black text-indigo-700\">{summary?pct(summary.completion_rate):\"Chưa có dữ liệu\"}</div></div>{summary&&<div className=\"mt-3\"><div className=\"h-2 overflow-hidden rounded-full bg-slate-100\"><div className={\"h-full rounded-full \"+tone(summary.completion_rate)} style={{width:Math.max(1,Math.min(100,summary.completion_rate||0))+\"%\"}}/></div><div className=\"mt-2 flex justify-between text-[10px] text-slate-400\"><span>{summary.learner_count} người học · {summary.attempt_count} lượt</span><span>Đạt {pct(summary.pass_rate)} · Điểm {val(summary.average_score)}</span></div></div>}</button>)}</div>\n        </section>\n\n        <aside className=\"space-y-5\">\n          <section className=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm\"><h2 className=\"font-black\">Chỉ số chất lượng</h2><div className=\"mt-5 space-y-4\">{[[\"Hoàn thành trung bình\",avgCompletion],[\"Tỉ lệ đạt trung bình\",avgPass],[\"Điểm trung bình\",avgScore]].map(([l,v])=><div key={String(l)}><div className=\"mb-1.5 flex justify-between text-xs\"><span className=\"font-bold text-slate-600\">{l}</span><span className=\"font-black\">{Math.round(Number(v))}{String(l).includes(\"Điểm\")?\"\":\"%\"}</span></div><div className=\"h-2 overflow-hidden rounded-full bg-slate-100\"><div className={\"h-full rounded-full \"+tone(Number(v))} style={{width:Math.max(1,Math.min(100,Number(v)))+\"%\"}}/></div></div>)}</div></section>\n          <section className=\"rounded-2xl border border-indigo-100 bg-indigo-50 p-5\"><div className=\"text-sm font-black text-indigo-900\">Đi sâu vào từng bài</div><p className=\"mt-2 text-xs leading-5 text-indigo-700\">Nhấp vào một bài giảng bên trái để xem mastery theo mục tiêu, attempts, learner progress và tích hợp LRS/xAPI.</p></section>\n        </aside>\n      </div>}\n    </div>\n  </main>;\n}\n");

const dashNavPath=path.join(root,"frontend/app/page.tsx");
let dashNav=fs.readFileSync(dashNavPath,"utf8");
dashNav=dashNav.replace('{ icon: "♟", label: "Học sinh", href: "/learn" }','{ icon: "♟", label: "Học sinh", href: "/students" }');
dashNav=dashNav.replace('{ icon: "▥", label: "Báo cáo", href: "#analytics" }','{ icon: "▥", label: "Báo cáo", href: "/reports" }');
fs.writeFileSync(dashNavPath,dashNav);
